it('keeps an ambiguous command fenced after reconnect GET reports ready before the delayed POST can be admitted',async()=>{
  let notify;let finish;const target={id:'lab',serviceIdentity:'same-lab',status:'connected'};window.desktopShell={getCurrentTarget:async()=>target,onTargetStatus:listener=>{notify=listener;return()=>{};}};api.executePrivateRKernel.mockImplementationOnce(()=>new Promise(resolve=>{finish=resolve;}));
  render(<RConsole {...publishingProps}/>);await start();fireEvent.change(screen.getByLabelText('Existing R binding'),{target:{value:'n'}});fireEvent.change(screen.getByLabelText('Saved output name'),{target:{value:'Saved n'}});fireEvent.click(screen.getByRole('button',{name:'Run R cell',exact:true}));await waitFor(()=>expect(finish).toBeTypeOf('function'));
  act(()=>notify({...target,status:'disconnected'}));act(()=>notify(target));await waitFor(()=>expect(api.getPrivateRKernel).toHaveBeenCalled());await waitFor(()=>expect(screen.getByRole('button',{name:'Refresh session status',exact:true})).toBeEnabled());
  expect(screen.getByText('Session ready · unsaved memory available')).toBeVisible();expect(screen.getByText('R command is running or awaiting confirmation. Session controls remain available.')).toBeVisible();expect(screen.getByRole('button',{name:'Run R cell',exact:true})).toBeDisabled();expect(screen.getByRole('button',{name:'Save object',exact:true})).toBeDisabled();
  await act(async()=>finish(entry));expect(screen.getByRole('button',{name:'Run R cell',exact:true})).toBeDisabled();fireEvent.click(screen.getByRole('button',{name:'Refresh session status',exact:true}));await waitFor(()=>expect(screen.getByRole('button',{name:'Refresh session status',exact:true})).toBeEnabled());expect(screen.getByRole('button',{name:'Run R cell',exact:true})).toBeDisabled();expect(api.executePrivateRKernel).toHaveBeenCalledTimes(1);expect(api.publishPrivateROutput).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole('button',{name:'Stop session',exact:true}));fireEvent.click(screen.getByRole('button',{name:'Stop and discard unsaved memory',exact:true}));await screen.findByText('Session stopped · unsaved memory lost');expect(screen.queryByText('R command is running or awaiting confirmation. Session controls remain available.')).not.toBeInTheDocument();expect(screen.getByRole('button',{name:'Start private session',exact:true})).toBeEnabled();
});
it('reconciles a nonterminal own acknowledged command only through its exact execution detail, without issuing another command',async()=>{
  api.executePrivateRKernel.mockResolvedValue({...entry,completionKnown:false,status:'unknown',result:null});api.getPrivateRExecution.mockResolvedValueOnce({...entry,completionKnown:false,status:'unknown',result:null});render(<RConsole {...props}/>);await start();fireEvent.click(screen.getByRole('button',{name:'Run R cell',exact:true}));await screen.findByText('Completion is unconfirmed. Refresh session status; this command will not be rerun automatically.');await waitFor(()=>expect(screen.getByRole('button',{name:'Refresh session status',exact:true})).toBeEnabled());expect(screen.getByRole('button',{name:'Run R cell',exact:true})).toBeDisabled();
  fireEvent.click(screen.getByRole('button',{name:'Refresh session status',exact:true}));await waitFor(()=>expect(screen.getByRole('button',{name:'Run R cell',exact:true})).toBeEnabled());expect(api.getPrivateRExecution).toHaveBeenLastCalledWith('project_one','pk_one','pex_one',expect.any(AbortSignal));expect(api.executePrivateRKernel).toHaveBeenCalledTimes(1);
});
it('keeps a lost save acknowledgement fenced after generic ready and publication-list GETs until an explicit memory discard',async()=>{
  let notify;let finish;const target={id:'lab',serviceIdentity:'same-lab',status:'connected'};window.desktopShell={getCurrentTarget:async()=>target,onTargetStatus:listener=>{notify=listener;return()=>{};}};api.publishPrivateROutput.mockImplementationOnce(()=>new Promise(resolve=>{finish=resolve;}));render(<RConsole {...publishingProps}/>);await start();fireEvent.change(screen.getByLabelText('Existing R binding'),{target:{value:'n'}});fireEvent.change(screen.getByLabelText('Saved output name'),{target:{value:'Saved n'}});fireEvent.click(screen.getByRole('button',{name:'Save object',exact:true}));await waitFor(()=>expect(finish).toBeTypeOf('function'));
  act(()=>notify({...target,status:'disconnected'}));act(()=>notify(target));await waitFor(()=>expect(api.getPrivateRKernel).toHaveBeenCalled());await waitFor(()=>expect(screen.getByRole('button',{name:'Refresh session status',exact:true})).toBeEnabled());expect(screen.getByRole('button',{name:'Save object',exact:true})).toBeDisabled();expect(screen.getByRole('button',{name:'Run R cell',exact:true})).toBeDisabled();
  await act(async()=>finish({publication,version:savedVersion}));api.listPrivateRPublications.mockResolvedValue({items:[{...publication,version:savedVersion}]});fireEvent.click(screen.getByRole('button',{name:'Refresh session status',exact:true}));await screen.findByRole('button',{name:'Inspect Saved cells · v1',exact:true});expect(screen.getByRole('button',{name:'Save object',exact:true})).toBeDisabled();expect(api.publishPrivateROutput).toHaveBeenCalledTimes(1);
  fireEvent.click(screen.getByRole('button',{name:'Stop session',exact:true}));fireEvent.click(screen.getByRole('button',{name:'Stop and discard unsaved memory',exact:true}));await screen.findByText('Session stopped · unsaved memory lost');expect(screen.queryByText(/Publication completion is unconfirmed/)).not.toBeInTheDocument();expect(screen.getByRole('button',{name:'Start private session',exact:true})).toBeEnabled();
});
