  api.publishPrivateROutput.mockResolvedValue({publication:{...publication,status:'unknown'},version:null});render(<RConsole {...publishingProps}/>);await start();fireEvent.change(screen.getByLabelText('Existing R binding'),{target:{value:'n'}});fireEvent.change(screen.getByLabelText('Saved output name'),{target:{value:'Saved n'}});fireEvent.click(screen.getByRole('button',{name:'Save object',exact:true}));await screen.findByText('Saved cells · object · unknown');await waitFor(()=>expect(screen.getByRole('button',{name:'Refresh session status',exact:true})).toBeEnabled());
